css:
.sl-cta-app {
    padding-block: clamp(3rem, 6vw, 5.5rem);
    border-block: 1px solid var(--smartlearn-card-border);
    font-family: var(--smartlearn-body-font, inherit);
}
.sl-cta-app .sl-text-primary { color: var(--smartlearn-primary) !important; }
.sl-cta-app .sl-text-muted { color: var(--smartlearn-text-muted) !important; }
.sl-cta-app.sl-bg-card { background-color: var(--smartlearn-card-bg) !important; }
.sl-cta-app .sl-bg-primary { background-color: var(--smartlearn-primary) !important; }

.sl-cta-app .sl-app-glow {
    width: 400px;
    height: 400px;
    filter: blur(60px);
    pointer-events: none;
}
.sl-cta-app .sl-app-preview {
    max-height: 500px;
    width: auto;
    height: auto;
    filter: drop-shadow(0 20px 30px rgba(0, 0, 0, 0.15));
}
.sl-cta-app .sl-app-btn {
    background-color: var(--smartlearn-bg);
    color: var(--smartlearn-text);
    border: 1px solid var(--smartlearn-card-border);
    min-height: 48px;
    transition: transform 0.2s ease, box-shadow 0.2s ease, border-color 0.2s ease;
}
.sl-cta-app .sl-app-btn:hover,
.sl-cta-app .sl-app-btn:focus-visible {
    border-color: var(--smartlearn-primary);
    color: var(--smartlearn-text);
    transform: translateY(-3px);
    box-shadow: 0 10px 20px rgba(0, 0, 0, 0.12);
}
.sl-cta-app .sl-app-btn:focus-visible {
    outline: 2px solid var(--smartlearn-primary);
    outline-offset: 2px;
}
.sl-cta-app .sl-app-kicker {
    font-size: 0.72rem;
    color: var(--smartlearn-text-muted);
}
.sl-cta-app .sl-app-store {
    font-size: 1rem;
    color: var(--smartlearn-text);
}
@media (prefers-reduced-motion: reduce) {
    .sl-cta-app .sl-hover-lift,
    .sl-cta-app .sl-app-btn { transition: none; }
    .sl-cta-app .sl-hover-lift:hover,
    .sl-cta-app .sl-app-btn:hover,
    .sl-cta-app .sl-app-btn:focus-visible { transform: none; box-shadow: none; }
}
